import {createFlight,stepFlight,checkSignal,FLIGHT_GOAL,FLIGHT_DURATION} from './game-model.js';
const q=s=>document.querySelector(s),dialog=q('#arcade'),flight=q('#flight'),ctx=flight.getContext('2d'),plane=new Image(),landscape=new Image();plane.src='assets/scout.png';landscape.src='assets/world.png';
let current='pilot',state=null,raf=0,last=0,paused=false,keys=new Set(),pointer=null,origin=null,trail=[],best=0,signalRound=1,sequence=[],entered=[],signalPhase='idle',signalTimers=new Set(),signalEpoch=0;
try{best=Number(localStorage.getItem('untitled-pilot-best'))||0}catch{}q('#pilot-record').textContent=`Best flight: ${best} sparks`;
function later(fn,ms){const id=setTimeout(()=>{signalTimers.delete(id);fn()},ms);signalTimers.add(id)}
function stopSignal(){signalEpoch++;signalTimers.forEach(clearTimeout);signalTimers.clear();document.querySelectorAll('[data-pad]').forEach(b=>{b.classList.remove('lit');b.disabled=true})}
function haltFlight(){cancelAnimationFrame(raf);raf=0;keys.clear();pointer=null}
function switchGame(game){haltFlight();stopSignal();current=game;dialog.dataset.game=game;q('#pilot-panel').hidden=game!=='pilot';q('#signal-panel').hidden=game!=='signal';q('#arcade-title').textContent=game==='pilot'?'Paper Pilot':'Signal Lost';document.querySelectorAll('[data-switch]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.switch===game)));if(game==='pilot'){state=null;paused=false;q('#flight-overlay').hidden=false;q('#flight-message').textContent='Ready for takeoff?';q('#launch').textContent='Launch flight ↗';q('#pause-flight').disabled=true;q('#pilot-score').textContent='0 / 15';q('#pilot-health').textContent='3 / 3';q('#pilot-time').textContent='40s';sizeFlight();drawFlight(performance.now());}else{signalPhase='idle';signalRound=1;q('#signal-round').textContent='ROUND 1 / 5';q('#signal-status').textContent='Ready to reconnect?';q('#start-signal').disabled=false;q('#start-signal').textContent='Connect the circuit ↗'}}
function openArcade(game,trigger){origin=trigger||document.activeElement;if(!dialog.open){dialog.showModal();document.documentElement.classList.add('arcade-open')}switchGame(game);q('#close-arcade').focus()}
document.querySelectorAll('[data-game]').forEach(b=>b.addEventListener('click',()=>openArcade(b.dataset.game,b)));document.querySelectorAll('[data-switch]').forEach(b=>b.addEventListener('click',()=>switchGame(b.dataset.switch)));
q('#close-arcade').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{haltFlight();stopSignal();document.documentElement.classList.remove('arcade-open');origin?.focus({preventScroll:true})});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function sizeFlight(){const r=flight.getBoundingClientRect();flight.width=900;flight.height=Math.max(280,Math.round(900*r.height/r.width))}
function launch(){haltFlight();sizeFlight();state=createFlight(flight.width,flight.height);paused=false;trail=[];q('#flight-overlay').hidden=true;q('#pause-flight').disabled=false;q('#pause-flight').textContent='Pause';flight.focus();last=performance.now();raf=requestAnimationFrame(tick)}
q('#launch').addEventListener('click',()=>{if(paused&&state?.status==='playing')resume();else launch()});
function pause(){if(!state||state.status!=='playing'||paused)return;paused=true;haltFlight();q('#flight-message').textContent='Flight paused';q('#launch').textContent='Resume flight ↗';q('#flight-overlay').hidden=false;q('#pause-flight').textContent='Resume'}
function resume(){paused=false;keys.clear();pointer=null;q('#flight-overlay').hidden=true;q('#pause-flight').textContent='Pause';last=performance.now();flight.focus();raf=requestAnimationFrame(tick)}
q('#pause-flight').addEventListener('click',()=>paused?resume():pause());
function finish(){haltFlight();best=Math.max(best,state.score);try{localStorage.setItem('untitled-pilot-best',String(best))}catch{}q('#pilot-record').textContent=`Best flight: ${best} sparks`;q('#flight-message').textContent=state.status==='won'?'15 sparks. Beautiful flying.':state.status==='crashed'?'A little ink. A fresh start?':`${state.score} sparks. Another adventure?`;q('#launch').textContent='Fly again ↗';q('#flight-overlay').hidden=false;q('#pause-flight').disabled=true}
function tick(now){if(!dialog.open||current!=='pilot'||paused)return;const dt=Math.min((now-last)/1000,.05);last=now;const input=pointer?{target:pointer}:{x:(keys.has('ArrowRight')||keys.has('d')?1:0)-(keys.has('ArrowLeft')||keys.has('a')?1:0),y:(keys.has('ArrowDown')||keys.has('s')?1:0)-(keys.has('ArrowUp')||keys.has('w')?1:0)};stepFlight(state,dt,input);trail.push({x:state.x-35,y:state.y+20});if(trail.length>32)trail.shift();drawFlight(now);q('#pilot-score').textContent=`${state.score} / ${FLIGHT_GOAL}`;q('#pilot-time').textContent=Math.max(0,Math.ceil(FLIGHT_DURATION-state.time))+'s';q('#pilot-health').textContent=`${state.health} / 3`;if(state.status!=='playing'){finish();return}raf=requestAnimationFrame(tick)}
function drawFlight(now){const W=flight.width,H=flight.height,t=state?.time||0;ctx.clearRect(0,0,W,H);ctx.fillStyle='#f5f3ee';ctx.fillRect(0,0,W,H);if(landscape.complete&&landscape.naturalWidth){ctx.save();ctx.globalAlpha=.22;const ih=H*.9,iw=ih*landscape.naturalWidth/landscape.naturalHeight,offset=(t*28)%iw;for(let bx=-offset;bx<W;bx+=iw)ctx.drawImage(landscape,bx,H-ih,iw,ih);ctx.restore()}ctx.save();ctx.strokeStyle='#ff6b1a';ctx.lineWidth=2;ctx.setLineDash([5,6]);ctx.beginPath();trail.forEach((a,i)=>i?ctx.lineTo(a.x,a.y):ctx.moveTo(a.x,a.y));ctx.stroke();ctx.restore();
for(const o of state?.objects||[]){ctx.save();ctx.translate(o.x,o.y);if(o.type==='spark'){ctx.rotate(now*.001+o.phase);ctx.fillStyle='#ff6b1a';ctx.beginPath();ctx.moveTo(0,-16);ctx.lineTo(5,-5);ctx.lineTo(16,0);ctx.lineTo(5,5);ctx.lineTo(0,16);ctx.lineTo(-5,5);ctx.lineTo(-16,0);ctx.lineTo(-5,-5);ctx.closePath();ctx.fill();ctx.strokeStyle='#ad3b00';ctx.lineWidth=1;ctx.stroke()}else{ctx.fillStyle='#252522';ctx.beginPath();for(let i=0;i<12;i++){const a=i/12*Math.PI*2,r=17+Math.sin(i*2.7+o.phase)*4;ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r)}ctx.closePath();ctx.fill();ctx.strokeStyle='#252522';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-27,-8);ctx.lineTo(-21,-4);ctx.moveTo(20,15);ctx.lineTo(28,20);ctx.stroke()}ctx.restore()}
const x=state?.x||W*.22,y=state?.y||H*.5;ctx.save();ctx.translate(x,y);ctx.rotate(state?((pointer?.y??state.y)-state.y)*.0008:-.08);ctx.globalAlpha=state?.invincible>0&&Math.floor(now/100)%2===0?.45:1;if(plane.complete&&plane.naturalWidth)ctx.drawImage(plane,-58,-(116*plane.naturalHeight/plane.naturalWidth)/2,116,116*plane.naturalHeight/plane.naturalWidth);else{ctx.fillStyle='#ff6b1a';ctx.beginPath();ctx.arc(0,0,20,0,7);ctx.fill()}ctx.restore()}
plane.addEventListener('load',()=>{if(dialog.open&&current==='pilot'&&!state)drawFlight(performance.now())});landscape.addEventListener('load',()=>{if(dialog.open&&current==='pilot'&&!state)drawFlight(performance.now())});
function point(e){const r=flight.getBoundingClientRect();return {x:(e.clientX-r.left)/r.width*flight.width,y:(e.clientY-r.top)/r.height*flight.height}}
flight.addEventListener('pointerdown',e=>{if(state?.status==='playing'&&!paused){pointer=point(e);flight.setPointerCapture(e.pointerId);flight.focus()}});flight.addEventListener('pointermove',e=>{if(state?.status==='playing'&&!paused&&(e.pointerType==='mouse'||flight.hasPointerCapture(e.pointerId)))pointer=point(e)});flight.addEventListener('pointerup',e=>{if(flight.hasPointerCapture(e.pointerId))flight.releasePointerCapture(e.pointerId)});
const pads=[...document.querySelectorAll('[data-pad]')];function light(index){pads[index].classList.add('lit');later(()=>pads[index].classList.remove('lit'),330)}
function showSequence(){stopSignal();signalPhase='watching';entered=[];q('#signal-round').textContent=`ROUND ${signalRound} / 5`;q('#signal-status').textContent='Watch the signal…';q('#start-signal').disabled=true;const epoch=signalEpoch;sequence.forEach((n,i)=>later(()=>{if(epoch===signalEpoch)light(n)},500+i*650));later(()=>{if(epoch!==signalEpoch)return;signalPhase='input';q('#signal-status').textContent='Your turn. Repeat the pattern.';pads.forEach(b=>b.disabled=false)},500+sequence.length*650)}
function startSignal(){stopSignal();signalRound=1;sequence=Array.from({length:3},()=>Math.floor(Math.random()*4));showSequence()}
q('#start-signal').addEventListener('click',startSignal);
function enterSignal(n){if(signalPhase!=='input')return;light(n);entered.push(n);const result=checkSignal(sequence,entered);if(result==='wrong'){signalPhase='lost';pads.forEach(b=>b.disabled=true);q('#signal-status').textContent='Signal lost. Give it another try.';q('#start-signal').disabled=false;q('#start-signal').textContent='Reconnect ↗'}else if(result==='complete'){pads.forEach(b=>b.disabled=true);if(signalRound===5){signalPhase='won';q('#signal-status').textContent='Circuit complete. All five rounds!';q('#start-signal').disabled=false;q('#start-signal').textContent='Play again ↗'}else{signalPhase='between';q('#signal-status').textContent='Connected. One more signal…';later(()=>{signalRound++;sequence.push(Math.floor(Math.random()*4));showSequence()},900)}}}
pads.forEach((b,i)=>b.addEventListener('click',()=>enterSignal(i)));
addEventListener('keydown',e=>{if(!dialog.open)return;if(current==='pilot'&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d','W','A','S','D'].includes(e.key)){e.preventDefault();keys.add(e.key.length===1?e.key.toLowerCase():e.key);pointer=null}else if(current==='pilot'&&e.code==='Space'&&state?.status==='playing'&&e.target===flight){e.preventDefault();paused?resume():pause()}else if(current==='signal'&&/^[1-4]$/.test(e.key)){e.preventDefault();enterSignal(Number(e.key)-1)}});addEventListener('keyup',e=>keys.delete(e.key.length===1?e.key.toLowerCase():e.key));
document.addEventListener('visibilitychange',()=>{if(document.hidden&&dialog.open){if(current==='pilot')pause();else if(['watching','input','between'].includes(signalPhase)){stopSignal();signalPhase='idle';q('#signal-status').textContent='Signal paused. Reconnect when ready.';q('#start-signal').disabled=false;q('#start-signal').textContent='Reconnect ↗'}}});addEventListener('blur',()=>{keys.clear();if(dialog.open&&current==='pilot')pause()});

addEventListener('resize',()=>{if(!dialog.open||current!=='pilot')return;const oldW=flight.width,oldH=flight.height;sizeFlight();if(state){const sx=flight.width/oldW,sy=flight.height/oldH;state.x*=sx;state.y*=sy;state.objects.forEach(o=>{o.x*=sx;o.y*=sy});state.width=flight.width;state.height=flight.height;trail=[];pointer=null;pause()}drawFlight(performance.now())});
